# encoding: utf-8
# =============================================================================
#  SoundStudio_House_BIM.rb  -  บ้านพักอาศัย ค.ส.ล. 2 ชั้น "Sounds studio"  โมเดล BIM + โครงสร้าง (SketchUp Ruby)  v1.1
#  แหล่งข้อมูล: แบบชุด ผังพื้นชั้นล่าง/ชั้นบน (1:100) ผังหลังคา รูปด้าน 1-4 รูปตัด A-A B-B (1:75) + ภาพ render 2 + มุมมอง SketchUp 3
#
#  โครงสร้าง : ฐานราก F1 ตอม่อ เสา C1 (0.20) / C2 (แกน ค.ส.ล. หุ้มไม้) คานคอดิน GB1 คานชั้นบน FB1/FB2 คานรับหลังคา RB1/RB2/TB1
#              พื้น S1-S4 บันได ค.ส.ล. 21 ลูกตั้ง  โครงหลังคาเหล็ก: อะเส C100 จันทัน 2C100@1.00 อกไก่ 2C150 ขื่อ+โครงถัก แป □25@0.30  (138 ชิ้น)
#  งานระบบ   : สุขภัณฑ์ 4 ห้องน้ำ ท่อน้ำดี/น้ำร้อน ถังน้ำ 2,000 ล. + ปั๊ม ฮีตปั๊ม 300 ล. ท่อโสโครก ถังบำบัด บ่อดักไขมัน รางน้ำ ท่อระบาย บ่อพัก แอร์ 6 ชุด
#  ไฟฟ้า     : มิเตอร์ 3 เฟส 15(45)A สายเมนใต้ดิน ตู้ไฟ ดวงโคม หลักดิน
#  สถาปัตย์  : ผนังภายนอก/ภายใน/ผนังคอนกรีตเซาะร่อง เจาะช่องเปิดจริง ประตู D2-D7 หน้าต่าง W1-W9  หลังคากระเบื้อง CPAC Monier 30° + ช่องเปิดหลังคา 2 ช่อง
#              ระแนงไม้ 20@37 มม. ราวเหล็ก ปิดเชิงชายไม้ ครีบผนังด้านข้าง ช่องท่อ  ภายนอก: ที่จอดรถ 2 คัน ทางลาด สวน บันไดขึ้นเฉลียง
#  รวม 419 องค์ประกอบ  ทุกชิ้นเป็น Group: IFC 2x3 classification + attribute 'SSH_BIM' + Tag
#
#  วิธีใช้ (Window > Ruby Console):
#      load 'C:/path/SoundStudio_House_BIM.rb'
#      SSHBIM.build                        # สร้างโมเดลทั้งหลัง (ลบของเดิมที่สคริปต์นี้สร้างก่อน)
#      SSHBIM.build(only: [:structure])    # :structure / :architecture / :mep / :site  เลือกบางหมวด
#      SSHBIM.report                       # ปริมาณงาน + ตารางประตูหน้าต่าง
#      SSHBIM.export_csv('C:/temp/ssh')    # เขียน _qto.csv และ _schedule.csv
#      SSHBIM.clashes                      # ตรวจชนกัน (bounding box) งานสถาปัตย์ x โครงสร้าง
#      SSHBIM.show(:structure)             # :structure / :architecture / :mep / :site / :all
#      SSHBIM.diag                         # นับชิ้นต่อ Tag + สถานะซ่อน/แสดง + ชิ้นที่สร้างไม่สำเร็จ
#      SSHBIM.validate                     # ตรวจความถูกต้องของข้อมูล DATA (ชื่อซ้ำ วัสดุ/ชั้นไม่มี กล่องเสื่อม) ใช้ได้นอก SketchUp
#
#  หน่วย = เมตร ; X = แนวกริด 1 -> 3 (0 .. 11.00, ทิศเหนือ = +X ตามลูกศรในแบบ) ; Y = แนวกริด E -> A (E 0, D 6.00, C 8.00, B 13.00, A 18.40)
#  Z: ดิน ±0.00 ; พื้นชั้นล่าง +0.60 ; พื้นชั้นบน +4.56 ; หลังอะเสเหล็ก +7.78 ; สูงสุดหลังคา +11.20 ; หลังคาลาด 30° สันหลังคาที่ Y = 13.20
#  ขนาดโครงสร้างจาก calc.py (ACI 318-19 / AISC 360) — ดินสมมติ qa 100 kPa ยังไม่มีผลเจาะสำรวจดิน ระบุไว้ใน attribute 'Note' — ต้องให้วิศวกรโยธาตรวจรับรอง
# =============================================================================
